"use client";
/* Crt, from the Piixpal shadcn registry. Options: https://piixpal.vercel.app/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Crt(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("crt"); }, []);
  return React.createElement("piix-sprite", { "name": "crt", ...piixAttrs(props) });
}

export default Crt;
